thm fast_extract:
    ? forall t R:
        exist x R st {x = t}
        =>:
            exist y R st {y = t}
    obtain u from exist x R st {x = t}
    witness exist y R st {y = t} from u

thm fast_not_exist:
    ? forall t R:
        not exist x R st {x = t and x != t}
    by contra:
        ? not exist x R st {x = t and x != t}
        obtain u from exist x R st {x = t and x != t}
        impossible u != t
